import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`course-lead-magnet`,heroTitle:`Build lead magnets for your course in minutes`,heroSubtitle:`Perplexity Computer analyzes your course, generates lead magnet ideas, and maps out your entire funnel strategy — automatically.`,inputUrlCta:`Generate my lead magnets`,inputUrlPlaceholder:`yourcourse.com`,inputUrlPrefill:`Go to {url} and do a deep analysis of this online course — extract the topic, target audience, curriculum structure, key learning outcomes, pricing, and unique selling points. Then create a comprehensive lead magnet strategy to drive new students into the funnel. Deliver: 1) Five lead magnet ideas ranked by conversion potential — including mini courses, PDF guides, checklists, and templates — with titles, descriptions, and outlines for each. 2) A quiz funnel concept with 8-10 questions that segments prospects by skill level and recommends the course, plus a results page outline for each segment. 3) Five content ideas (blog posts, social posts, short videos) designed to attract the course's ideal student and link back to the lead magnets. 4) A webinar plan including a compelling title, a minute-by-minute agenda, three key teaching points that tease the full course, and a pitch sequence for the close. 5) A funnel map showing how each lead magnet connects to an email nurture sequence and the course sales page. Format everything as a detailed, actionable playbook I can execute immediately.`,heroOverlaySteps:[`Analyzing your course content, audience, and value proposition`,`Generating lead magnet ideas — mini courses, quizzes, and guides`,`Building webinar plans and content strategies for your funnel`,`Lead magnets, quiz funnels, and webinar playbook — ready to launch`],generatingSteps:[`Visiting {url} to extract your course topic, curriculum, audience, and positioning`,`Designing an agent to generate high-converting lead magnets and quiz funnels for your course`,`Configuring content strategy, webinar planning, and funnel mapping modules`,`Setting up your complete lead magnet playbook with actionable deliverables`],featureSectionTitle:`From course URL to full funnel strategy`,featureCardTitles:[`Connects to your course stack`,`Outputs you can launch`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Google Drive, Canva, Gmail — Computer pushes your lead magnets and funnel plans straight into the tools you already use.`,`Mini course outlines. Quiz funnel scripts. Webinar agendas. Content calendars. Email nurture sequences. A complete funnel map tying it all together.`],capabilitySectionTitle:`Your growth marketer, on autopilot`,capabilitySectionSubtitle:`Paste your course URL, step away, come back to a complete lead magnet strategy.`,capabilityCards:[{title:`Course Analysis`,description:`Computer can study your course page — topic, curriculum, pricing, audience, and positioning — to build lead magnets that actually match your offer.`},{title:`Lead Magnet Ideas`,description:`Computer can generate mini courses, PDF guides, checklists, and templates — each ranked by conversion potential with full outlines ready to build.`},{title:`Quiz Funnels`,description:`Computer can design interactive quiz funnels that segment prospects by skill level and recommend your course — complete with questions and results pages.`},{title:`Connect Your Tools`,description:`Computer can push deliverables to Google Sheets, Notion, Google Drive, Canva, and Gmail — build workflows across your entire course marketing stack.`},{title:`Remember & Improve`,description:`Computer can remember your course details, past lead magnets, and funnel performance across sessions — so every strategy gets sharper over time.`},{title:`Monitor & Refresh`,description:`Computer can track your course page for updates and flag when lead magnets need refreshing to match new pricing, modules, or positioning.`}]});export{t as default};
